/* ---------- report generation and scoring ---------- */
const seeded=h=>()=>{h|=0;h=h+0x6D2B79F5|0;let t=Math.imul(h^h>>>15,1|h);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296};
function gen(fn,size,sample){const SP=sample?SMP[mine.filter(x=>x.file=="annual-report-sample.pdf").length%SMP.length]:null,nm=sample?SP.n:"Demo Company",ym=fn.match(/(19|20)\d\d/),year=sample||!ym?"2025":ym[0];
let h=0;for(const ch of fn)h=(h*31+ch.charCodeAt(0))>>>0;const r=seeded(h);
let eq=Math.round(600+r()*4400),np=Math.round(eq*(6+r()*22)/100),debt=Math.round(eq*(.1+r()*2)),prev=Math.round(1500+r()*8500),cur=Math.round(prev*(1+(-6+r()*28)/100)),ocf=Math.round(np*(r()<.12?-.3:.4+r()*1.1)),p=[0,1,2,3,4].map(()=>40+Math.floor(r()*100)),st=["Valid","Valid","Valid","Valid"];
if(h%7==0){ocf=null;st[2]="Missing"}else if(h%5==0)st[1]="Flagged";
if(sample){[eq,np,debt,ocf,prev,cur]=SP.v;p=[84,91,96,78,0];st=["Valid","Valid","Valid","Valid"]}
return{t:"report",id:"r"+Date.now(),ts:Date.now(),file:fn,size:Math.round(size/1048576*100)/100,name:nm,year,inp:{eq,np,debt,ocf,prev,cur},st,pg:[[p[0],p[1]],[p[1],p[0]],[p[2]],[p[3]]],pf:prefs(),saved:false,wrong:[],ok:false}}
function calc(r){const i=r.inp,has=(...v)=>v.every(x=>x!=null&&!isNaN(x)),roe=has(i.np,i.eq)&&i.eq>0?i.np/i.eq*100:null,de=has(i.debt,i.eq)&&i.eq>0?i.debt/i.eq:null,g=has(i.cur,i.prev)&&i.prev>0?(i.cur-i.prev)/i.prev*100:null,
sc=[roe==null?null:clamp(Math.round(roe/25*100)),de==null?null:clamp(Math.round(100-de/2*100)),i.ocf==null?null:i.np>0?clamp(Math.round(40+i.ocf/i.np*50)):(i.ocf>0?60:25),g==null?null:clamp(Math.round(50+g*3))],
dp=[roe==null?"Not available":roe.toFixed(1)+"%",de==null?"Not available":de.toFixed(2),i.ocf==null?"Not available":rs(i.ocf),g==null?"Not available":g.toFixed(1)+"%"],M=MN.map((n,k)=>({n,k,status:r.st[k],score:sc[k],disp:dp[k]})),v=M.filter(m=>m.status=="Valid"&&m.score!=null),score=v.length?Math.round(v.reduce((a,m)=>a+m.score,0)/v.length):0;
return{M,score,roe,de,g,label:score>=80?"Strong fundamental strength":score>=55?"Moderate fundamental strength":"Limited fundamental strength"}}
const ill=r=>r.src!="pdf",NA="This metric is unavailable because the required values were not found or were flagged.";
function mySummary(r,c){const pf=r.pf||{},i=r.inp,det=pf.exp=="Advanced"||pf.lang=="Detailed financial English",fm={"Profitability":0,"Debt and financial safety":1,"Cash flow strength":2,"Revenue growth":3}[pf.focus],ok=k=>c.M[k].status=="Valid"&&c.M[k].score!=null;
const S=[ok(0)?`The company earns ₹${Math.round(c.roe)} profit for every ₹100 of shareholders’ money.`:NA,ok(1)?`For every ₹100 of shareholders’ money, the company has about ₹${Math.round(c.de*100)} of debt.`:NA,ok(2)?(i.ocf>0?`The company’s core business brought in ${rs(i.ocf)} in cash.`:"The company’s core business used cash instead of generating it."):NA,ok(3)?`Revenue ${c.g>=0?"grew":"fell"} by ${Math.abs(c.g).toFixed(1)}% compared with the previous year.`:NA];
const D=[ok(0)?`ROE = Net Profit ÷ Shareholders’ Equity = ${rs(i.np)} ÷ ${rs(i.eq)} = ${c.roe.toFixed(1)}%. ${RULE[0]}`:NA,ok(1)?`D/E = Total Debt ÷ Shareholders’ Equity = ${rs(i.debt)} ÷ ${rs(i.eq)} = ${c.de.toFixed(2)}. ${RULE[1]}`:NA,ok(2)?`Operating cash flow = ${rs(i.ocf)}. ${RULE[2]}`:NA,ok(3)?`Revenue Growth = [(${rs(i.cur)} − ${rs(i.prev)}) ÷ ${rs(i.prev)}] × 100 = ${c.g.toFixed(1)}%. ${RULE[3]}`:NA],T=det?D:S;
const body=fm!=null?`<p><b>You wanted to understand ${pf.focus.toLowerCase()} first.</b></p><p>${T[fm]}</p>`:`<p><b>Overall fundamental health</b></p>`+T.map(x=>`<p>${x}</p>`).join("");
return`<div class="card"><h2>Summary for you</h2>${body}<small>${det?"Detailed view":"Simple view"} · FinScore ${c.score}/100${ill(r)?" · illustrative values":" · values read from your PDF"}</small></div>`}
const simple=(r,c)=>{const ok=k=>c.M[k].status=="Valid"&&c.M[k].score!=null,i=r.inp,P=[];if(ok(0))P.push(`it earns about ₹${Math.round(c.roe)} for every ₹100 of shareholders’ money`);if(ok(1))P.push(`it owes about ₹${Math.round(c.de*100)} per ₹100 of that money`);if(ok(2))P.push(i.ocf>0?"its main business produces cash":"its main business is using cash");if(ok(3))P.push(`revenue ${c.g>=0?"grew":"fell"} ${Math.abs(c.g).toFixed(1)}%`);
return`${r.name} scores ${c.score} out of 100, which means ${c.label.toLowerCase()}. In simple words: ${P.length?P.join(", ")+".":"there were not enough valid values to explain."}${P.length<4?" Some metrics were unavailable, so they are left out.":""} This is an analysis aid, not advice.`};
