function nameFrom(fn){return fn.replace(/\.pdf$/i,"").replace(/[-_]+/g," ").replace(/\b(annual|report|ar|fy|sample)\b/ig,"").replace(/\b(19|20)\d\d(-\d\d)?\b/g,"").replace(/\s+/g," ").trim().replace(/\b\w/g,c=>c.toUpperCase())||"Uploaded Company"}
const MAXMB=30,PDFJS="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/";let pdfP=null;
function loadPdfjs(){if(window.pdfjsLib)return Promise.resolve(window.pdfjsLib);if(pdfP)return pdfP;return pdfP=new Promise((res,rej)=>{const s=document.createElement("script");s.src=PDFJS+"pdf.min.js";s.onload=async()=>{const L=window.pdfjsLib;try{const r=await fetch(PDFJS+"pdf.worker.min.js");if(!r.ok)throw 0;L.GlobalWorkerOptions.workerSrc=URL.createObjectURL(new Blob([await r.text()],{type:"text/javascript"}))}catch(e){L.GlobalWorkerOptions.workerSrc=PDFJS+"pdf.worker.min.js"}res(L)};s.onerror=()=>{pdfP=null;rej(new Error("Could not load the PDF reader. Check your internet connection and try again."))};document.head.appendChild(s)})}
const UNITS={crore:1,crores:1,lakh:.01,lakhs:.01,million:.1,millions:.1,billion:100,billions:100,thousand:1e-4,thousands:1e-4};
const unitIn=t=>{const m=t.match(/(?:₹|rs\.?|inr|in)\s*(?:in\s*)?(crores?|lakhs?|millions?|billions?|thousands?)\b/i);if(!m)return null;const n=m[1].toLowerCase();return{u:UNITS[n],n:n.replace(/s$/,""),d:true}};
const pnum=t=>{t=t.trim();if(/^[-–—]$/.test(t))return 0;if(!/^\(?-?[\d,]+(?:\.\d+)?\)?$/.test(t))return null;const v=parseFloat(t.replace(/[^\d.]/g,""));return isNaN(v)?null:(/^\(|^-/.test(t)?-v:v)};
function rowVals(l){const n=[];l.slice(1).forEach(c=>c.split(/\s+/).forEach(t=>{const v=pnum(t);if(v!=null)n.push(v)}));if(n.length>=3&&Number.isInteger(n[0])&&Math.abs(n[0])<100)n.shift();return n}
function pick(pages,rx,skip,need=1){let best=null;for(const P of pages)for(const l of P.lines){const lab=l[0];if(!rx.test(lab)||(skip&&skip.test(lab)))continue;const n=rowVals(l);if(n.length<need)continue;const sc=(P.fs?2:0)+(P.cons?1:0);if(!best||sc>best.sc)best={sc,vals:n.slice(0,need).map(v=>Math.round(v*P.un.u*100)/100),p:P.p,P,lab}}return best}
